import pandas as pd

def find_requesting_users(confirmations: pd.DataFrame) -> pd.DataFrame:
    df = confirmations.sort_values(['user_id', 'time_stamp'])
    df['diff'] = df.groupby('user_id')['time_stamp'].diff()
    qual = df[df['diff'] <= pd.Timedelta(hours=24)]
    return qual[['user_id']].drop_duplicates()
